node -e " const fs=require('fs');let s=fs.readFileSync('src/worker/pool.mjs','utf8'); const rep=(a,b)=>{ if(!s.includes(a)) throw new Error('missing '+a); s=s.replace(a,b); }; rep("import { fork } from 'node:child_process';", "import { fork } from 'node:child_process';
import { randomBytes } from 'node:crypto';"); rep('// WorkerPool: starts worker processes, replaces the ones that die, and returns
// jobs to the queue when their lease runs out.', '// WorkerPool: starts worker processes, replaces the ones that die, gives a dead
// worker\'s jobs back at once, and returns jobs to the queue when a lease runs out.'); rep('    this.incarnation = 0;', '    // Worker ids are shared by every process on the queue, and a reclaim goes by id,
    // so they must not collide with another pool\'s (or an earlier run\'s) workers.
    this.poolId = randomBytes(4).toString('hex');
    this.pendingReclaims = new Set();
    this.incarnation = 0;'); rep('    try {
      this.queue.reapExpired();
    } catch (err) {
      this.emit('error-event', err);
    }
  }', '    for (const workerId of [...this.pendingReclaims]) this.#reclaim(workerId);
    try {
      this.queue.reapExpired();
    } catch (err) {
      this.emit('error-event', err);
    }
  }

  // Only ever for a worker this pool has seen exit. A failure is retried on the next
  // reaper tick; until then the lease runs out on its own.
  #reclaim(workerId) {
    try {
      this.queue.reclaimWorker(workerId, { reason: 'worker exited' });
      this.pendingReclaims.delete(workerId);
    } catch (err) {
      this.pendingReclaims.add(workerId);
      this.emit('error-event', err);
    }
  }'); rep('const workerId = \`w\${this.incarnation}\`;', 'const workerId = \`w\${this.incarnation}.\${this.poolId}\`;'); rep("    log.info('worker exited', { workerId, code, signal, stopping: this.stopping });
", "    log.info('worker exited', { workerId, code, signal, stopping: this.stopping });
    this.#reclaim(workerId);
"); fs.writeFileSync('src/worker/pool.mjs',s); " && git diff --stat

